import { Component, OnInit } from '@angular/core';
import { ActivatedRoute, Router } from '@angular/router';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { ProfService } from 'src/app/core/services/prof.service';

@Component({
  selector: 'app-join-class',
  standalone: true,
  imports: [CommonModule, FormsModule],
  templateUrl: './join-class.component.html',
  styleUrls: ['./join-class.component.scss']
})
export class JoinClassComponent implements OnInit {
  code = '';
  classData: any = null;
  msg = '';
  loading = false;
  profSlug: string | null = null;

  constructor(
    private route: ActivatedRoute,
    private profService: ProfService,
    private router: Router
  ) {}

  ngOnInit() {
    // Récupère le slug du prof (optionnel)
    this.profSlug = this.route.snapshot.queryParamMap.get('prof');

    // Si le code est déjà passé (ex: ?code=CL-123456)
    const queryCode = this.route.snapshot.queryParamMap.get('code');
    if (queryCode) {
      this.code = queryCode;
      this.join();
    }
  }

  join() {
    if (!this.code.trim()) {
      this.msg = '⚠️ Code requis';
      return;
    }

    this.loading = true;
    this.profService.getClassByCode(this.code).subscribe({
      next: (res: any) => {
        this.loading = false;
        if (res && res.id) {
          this.classData = res;
          // Redirige vers la page des fichiers de cette classe
          this.router.navigate(['/student/class', res.id]);
        } else {
          this.msg = '❌ Classe introuvable';
        }
      },
      error: (err: any) => {
        console.error('Erreur recherche classe:', err);
        this.msg = '❌ Classe introuvable';
        this.loading = false;
      }
    });
  }
}
